// Session-launch composition for TerminalView (#1645). Pure, React-free builders that turn the
// current app-store snapshot into the exact payloads the PTY launch path feeds to the Tauri
// commands (`pty_create` env, `ensure_session_settings`, and the resolved init command). Extracted
// verbatim from TerminalView's mount effect so the renderer stays a lean terminal host while the
// provider/MCP/skills/permissions/init-cmd assembly lives here.
//
// BEHAVIOR CONTRACT: each builder reads the store via the snapshot it's handed and is called at the
// SAME point in the launch sequence as the inline code it replaced. Every read in the original blocks
// was synchronous (no `await` between them), so a single snapshot is identical to the original's
// repeated `useAppStore.getState()` calls. Do not change what is computed, only where it lives.

import { resolveLlmConfig, bscAgentEnv, aiderEnv, providerNeedsBscAgent, DEFAULT_LOCAL_BASE_URL, type LlmConfig } from "@/shared/lib/core/llmConfig";
import { MODEL_IDS } from "@/app/console/lib/models";
import { resolvePersonaMcp, toBscAgentMcp, resolvePersonaHooks, toSessionPayloads, BUILTIN_MCP_SERVERS } from "@/features/mcp";
import { effectiveSessionSkills, expandGroups, toSkillCfgs } from "@/features/skills";
import { resolveInitCmd, harnessResumes } from "@/app/console/lib/resumeClaude";
import { isManualPaneId } from "@/app/console/lib/paneIdentity";
import { roleCapability, capabilitySurfaces, surfacesFromAllow, roleDeniedCommands, roleWriteRules, roleDeniedTools, bscAgentPerms, scopeWriteGlobs, sessionScopes, restrictedRoleCommands, isRestrictedRole, editPathRule, HARVEST_ROOT_APP_REPO, HARVEST_ROOT_PROJECTS, type SessionRole, type RoleCapability } from "@/shared/lib/session/sessionRoles";
import { deniableSurfaceNames } from "@/shared/lib/session/surfaceCatalog";
import { isFullCapabilitySession, isStudioSessionPaneId, surfaceRoleForPaneId } from "@/shared/lib/session/systemSessions";
import { TURN_ACCOUNTING_HOOKS } from "@/shared/lib/session/turnHooks";
import { studioRoleForPaneId } from "@/features/studio-sessions";
import { resolveProfileSettings } from "@/shared/lib/security/profileEnforcement";
import { flowPermissionRules, flowGrantedPushCommands } from "@/features/planner";
import type { ConsoleProvider, ProviderLaunchConfig } from "@/app/console/lib/providers";
import type { AppStore } from "@/store/types";

/**
 * Base session env for `pty_create`. Carries `GH_TOKEN` for gh/git-over-https; the write-scope globs
 * (`BSC_SCOPE_GLOBS`) for the `bsc-scope` PreToolUse hook on any gated pane; the role's per-store
 * access scopes (`BSC_SCOPES`, #2470) for the store CLIs' runtime write check; and, for a bsc-agent
 * session, the selected LLM provider/model/key, role-derived perms (`BSC_AGENT_PERMS`) and resolved
 * MCP servers (`BSC_AGENT_MCP`). Returns undefined when nothing needs to be injected.
 *
 * @param s        store snapshot taken at the launch point (after the claude-launch gate)
 * @param paneId   the pane being launched
 * @param providerId  the resolved provider id (default "claude")
 * @param ghToken  the repo-scoped or global GitHub token already resolved for this pane
 */
/** Sentinel `BSC_SCOPE_GLOBS` value meaning "deny ALL file writes" — set for a `code:none` role with
 *  no write globs so the `bsc-scope` PreToolUse hook hard-blocks every Edit/Write (a write-block that
 *  survives `bypassPermissions`, #1916 Step 3.5). MUST match the literal in `bsc-scope` (shell_rc.rs). */
export const SCOPE_DENY_ALL = "__bsc_deny_all__";

/** Where `bsc-sandbox` binds the static hook binary inside a namespace. Must match
 *  `HOOK_GUEST_PATH` in `crates/bsc-sandbox/src/lib.rs` — two sides hard-code it so it cannot
 *  drift, and the failure mode of a mismatch is a gate that silently never fires. */
export const HOOK_GUEST_PATH = "/bsc-hook";

/** The PreToolUse gates a SANDBOXED session gets, which is a strict SUBSET of the normal set —
 *  and the subset is the honest shape rather than a compromise.
 *
 *  Inside a mount namespace there is no `bsc` binary and no `BASH_ENV`, so every shell-based gate
 *  (`bsc-audit`, `bsc-mcp`, `bsc-taint`, `bsc-supply`, `bsc-fork`, `bsc-superseded`, `bsc-skill`,
 *  and the turn-accounting pair) cannot run at all. Emitting a command that cannot run is worse
 *  than emitting none: it reads like a working gate in every settings dump.
 *
 *  `bsc-confine` is dropped for the opposite reason — the mount namespace SUBSUMES it. An
 *  out-of-root path is absent rather than refused, for every descendant process.
 *
 *  What is left is exactly what a path-granular namespace cannot express, carried by the static
 *  binary bound at {@link HOOK_GUEST_PATH}:
 *    - `scope`     — write globs WITHIN the one read-write worktree
 *    - `bash-deny` — the shape of a command whose binary is present
 *
 *  THE LOSS IS REAL AND DELIBERATE: a sandboxed session has no tool-attempt telemetry and no
 *  supply-chain gate. Restoring either means widening `bsc-hook` or accepting `BASH_ENV`, and both
 *  are decisions rather than oversights. */
/** Everything the launch path needs to know about isolation for ONE pane, decided in one place.
 *
 *  This exists so the component does not have to. `TerminalView` composes settings BEFORE it
 *  computes the WSL distro, and the two reads are separated by an `await` — so working the decision
 *  out inline there means either duplicating the distro logic above its own definition, or hoisting
 *  a store snapshot across the await and quietly changing which state the later code sees. Both are
 *  worse than a pure function with tests. */
export interface SandboxPlan {
  backend: SandboxBackend;
  /** Passed as `pty_create`'s `sandbox_role`. Set ONLY for the namespace backend. */
  role?: SessionRole;
  /** Whether `buildSessionSettings` should emit the `/bsc-hook` list instead of the shell gates. */
  namespaceHooks: boolean;
}

/** The isolation plan for one pane.
 *
 *  `namespaceAvailable` comes from the `sandbox_available` command — the frontend cannot answer it
 *  (no platform probe, no plugin-os) and must not guess, because claiming a namespace that does not
 *  materialize drops the shell gates for a session that never got a cage.
 *
 *  **A namespace needs a ROLE.** `namespace_argv` refuses an absent or unrecognised one rather than
 *  launching unsandboxed, so a role-less pane (a plain manual console) is reported as its WSL/none
 *  answer instead — matching what the launcher will actually do rather than what we would prefer. */
/**
 * The roles the BACKEND refuses to cage, mirroring `UNCAGED_ROLES`
 * (`crates/bsc-sandbox` → `bsc-sandbox--profile.rs`).
 *
 * Each is uncaged because the cage cannot yet serve its store: it needs an outbox the way `/ui/out`
 * and `/plan/out` already exist, and until then a caged session would fail on its first instructed
 * command. That is a DECISION, not a fault.
 *
 * The frontend has to know it, because it decides something downstream of it: a namespace plan makes
 * `buildSessionSettings` emit the `/bsc-hook` guest paths. Planning a cage Rust then declines left
 * every one of these panes with hooks pointing at a path that exists only inside a namespace —
 * repaired on every launch, with the notice printed in the pane every time. Measured: 13 repairs in
 * one app run, the same panes over and over, because the writer kept regenerating what the repair
 * had just fixed.
 */
export const UNCAGED_ROLES: readonly SessionRole[] = [
  "designer",
  "architect",
  "librarian",
  "director",
  "integrator",
  // The surface OPERATOR. Uncaged for the general rule rather than a blocker of its own: a caged
  // session gets the read-only projections and deliberately NO `bsc` binary, and this role's whole
  // job is `bsc <noun>` — a noun chosen per SESSION, so there is not even one projection that could
  // be built for it. It would die on its first instructed command exactly as the designer did.
  //
  // It is here because giving the pane a ROLE AT ALL created the disagreement: while it had none,
  // `sandboxPlanFor`'s `!!role` was false and no cage was ever planned. The moment it got one the
  // frontend planned a namespace, Rust declined it, and every launch wrote `/bsc-hook` guest paths
  // that had to be repaired — the loop described above, reproduced.
  "operator",
  // The STEWARD (`a-network-gets-a-root-session-that-can-use-what-it-owns`) — a network's root
  // session. Uncaged for the architect's reason rather than the operator's: everything it reads lives
  // in the HOST's stores, and a cage binds a private HOME with no `~/.base-studio-code`. A caged
  // steward would answer "this network can do nothing" instead of failing — and for a read whose
  // entire value is freshness, a confident empty is the worst available outcome.
  "steward",
] as const;

/** Will the backend refuse to cage this role? */
export function isUncagedRole(role: SessionRole | undefined): boolean {
  return !!role && (UNCAGED_ROLES as readonly string[]).includes(role);
}

export function sandboxPlanFor(
  s: AppStore,
  paneId: string,
  namespaceAvailable: boolean,
): SandboxPlan {
  const role = paneRole(s, paneId);
  // The legacy WSL signal, read from the SAME store fields the distro block downstream reads, so the
  // two cannot disagree: the opt-in manual scratch shell (#1988), or an identity pane whose distro
  // fleetStartProject already set (#1994).
  const wslPlanned =
    // Optional-chained on purpose: this runs on the LAUNCH PATH, before anything guarantees
    // the map is populated, and an isolation decision must not be the thing that throws.
    (s.sandboxConsoles === true && isManualPaneId(paneId)) || !!s.paneWslDistro?.[paneId];
  const backend = resolveSandboxBackend({
    // ...and NOT for a role the backend will refuse to cage. Planning a namespace for one made
    // `buildSessionSettings` write `/bsc-hook` guest paths that Rust then had to repair on every
    // single launch — see `UNCAGED_ROLES`.
    namespaceAvailable: namespaceAvailable && !!role && !isUncagedRole(role),
    agentSandboxInstalled: wslPlanned,
  });
  return {
    backend,
    role: backend === "namespace" ? role : undefined,
    namespaceHooks: usesNamespaceHooks(backend),
  };
}

/** Which isolation backend a host can actually provide.
 *
 *  `"namespace"` — a Linux mount namespace (`bsc-sandbox`). The preferred one: cheapest, and the
 *    only one the escape test proves per-agent (measured 17 ms and 262 kB per agent).
 *  `"wsl"`       — the sealed WSL2 distro (#1988) with per-agent Linux users (#1994). Real
 *    isolation, already built, and what a WINDOWS host has. Retired once Windows is.
 *  `"none"`      — no isolation available; the PreToolUse hooks remain the whole floor. */
export type SandboxBackend = "namespace" | "wsl" | "none";

/** What the two capability probes reported. Kept as plain data so this stays pure and testable —
 *  the probes themselves are `sandbox_available` (cheap, sync) and `wsl_sandbox_status` (async and
 *  `spawn_blocking`, because a cold `wsl.exe` takes seconds and once froze the Settings window). */
export interface SandboxCaps {
  /** `sandbox_available()` — a Linux host with `bwrap` present. */
  namespaceAvailable: boolean;
  /** `wsl_sandbox_status().agentSandboxInstalled` — the sealed distro is imported. */
  agentSandboxInstalled: boolean;
}

/** The best isolation this host can give, preferring the namespace.
 *
 *  **This encodes the policy: sandboxed BY DEFAULT, with no toggle.** There is no "off" input —
 *  `"none"` means the host genuinely cannot isolate, never that someone declined. A setting that
 *  can turn isolation off is a setting that will be off on the machine where it mattered.
 *
 *  Preference order is not arbitrary. The namespace is per-agent (the escape test executes a
 *  sibling-worktree read and gets ENOENT), costs 17 ms and 262 kB per agent, and needs no
 *  provisioning. The distro is heavier and Windows-only, but it is REAL isolation and already
 *  satisfies #4260's raw-Bash cross-worktree criteria, so it is the right answer on a host with no
 *  mount namespace rather than a fallback to nothing.
 *
 *  It fails CLOSED by construction: an unavailable backend is never claimed, because claiming one
 *  makes the caller drop the shell gates for a session that never got a cage. */
export function resolveSandboxBackend(caps: SandboxCaps): SandboxBackend {
  if (caps.namespaceAvailable) return "namespace";
  if (caps.agentSandboxInstalled) return "wsl";
  return "none";
}

/** Does this backend replace the PreToolUse hooks with the in-namespace binary?
 *
 *  ONLY the mount namespace does. A WSL distro session still runs the normal shell gates — it has
 *  `BASH_ENV`, it has `bsc`, and nothing about it makes `bsc-confine` unreachable — so swapping its
 *  hook list for `/bsc-hook` would DELETE working gates and point at a binary that is not bound
 *  there. That asymmetry is the whole reason this is a separate question from "is it sandboxed". */
export function usesNamespaceHooks(backend: SandboxBackend): boolean {
  return backend === "namespace";
}

export const SANDBOXED_HOOKS = [
  { event: "PreToolUse", matcher: "Edit|Write|MultiEdit|NotebookEdit", command: `${HOOK_GUEST_PATH} scope` },
  { event: "PreToolUse", matcher: "Bash", command: `${HOOK_GUEST_PATH} bash-deny` },
];

/**
 * The pane's role gate. Prefers the store, then DERIVES it from the pane id for an app-owned studio
 * session (#3423).
 *
 * The store entry is written by `seedStudioLaunchState`, which only runs when `StudioSessionMount`
 * renders — and that happens only for a studio in `wantedStudios`, a transient set (absent from
 * `partialize`) that is empty after every app restart. A studio opened in that window reached this
 * function with NO role, and a missing role means no role gate, no `restrictedAllow` and no denies: a
 * fully unconfined shell on the most restricted surface in the app. A studio's pane id is stable and
 * app-owned, so it is sufficient on its own — confinement now travels with the session's identity
 * rather than with setup order. Any other pane keeps the store as its only authority.
 */
function paneRole(s: AppStore, paneId: string): SessionRole | undefined {
  // The SURFACE sessions join the same rule, for the same reason and after the same bug: nothing
  // writes `paneRoles` for one, and they are not in the fixed studio registry, so both branches above
  // missed them and they launched with no role at all — see `surfaceRoleForPaneId`.
  return s.paneRoles[paneId] ?? studioRoleForPaneId(paneId) ?? surfaceRoleForPaneId(paneId) ?? undefined;
}

/**
 * The MCP server ids a pane's PERSONA carries — the only input to its server set.
 *
 * Mirrors `paneCapability` right below: both answer "what does this pane get" by looking up the
 * pane's persona, because the persona IS the launch primitive. A pane with no persona (an
 * interactive console, a pane whose persona was deleted) carries nothing and gets the ambient
 * built-ins alone — which is a working session, not a broken one.
 */
/** The persona a pane runs as, or undefined. The one lookup every "what does this pane get"
 *  question goes through — capability, MCP servers, and now hooks. */
function panePersona(s: AppStore, paneId: string) {
  return s.personas?.find((p) => p.id === s.panePersonas?.[paneId]);
}

/** The MCP server ids this pane's persona carries.
 *
 *  Exported so `pty_create` can be handed the SAME ids `buildAgentEnv` resolved from
 *  (`the-launch-resolves-its-own-mcp-servers-instead-of-receiving-them`) — one definition rather than
 *  two, the same reason `paneAccessCapability` is exported. A second copy in the view would let the
 *  backend narrow a resolution the env was not built from, and the drift would surface as a server
 *  silently dropped from `$BSC_AGENT_MCP`. */
export function paneMcpIds(s: AppStore, paneId: string): string[] {
  return panePersona(s, paneId)?.mcp ?? [];
}

/**
 * The pane's CAPABILITY — its persona's own floor when it has one, else its role's row.
 *
 * This is the point of `personas-are-the-launch-primitive`. `roleCapability(role)` answers "what may
 * this KIND of session do"; a persona may be narrower than its kind, and before this the narrowing was
 * discarded exactly here. A user persona derived from `worker` with a tighter floor was assigned to a
 * pane, `applyPersonaToPane` stored `persona.role`, and the launch read the full worker row — the one
 * moment the narrowing had to survive was the one place it did not.
 *
 * The role remains the FALLBACK, not a second source: a plain console, a fleet pane seeded before any
 * persona existed, and a studio whose id resolves through `studioRoleForPaneId` all still launch
 * exactly as they did. `role` is carried on the returned capability either way, because the launch
 * rules downstream branch on it (`hasScopedWriteCarveOut`, the director/planner file denies).
 */
function paneCapability(
  s: AppStore,
  paneId: string,
  override: Partial<RoleCapability> = {},
): RoleCapability | null {
  const persona = s.personas?.find((p) => p.id === s.panePersonas?.[paneId]);
  if (persona?.floor) {
    // A persona's floor is the whole capability; `role` comes along so downstream branching still
    // works, and the caller's override (a worker's owned globs) still wins, as it does for a role.
    // Converted FIELD BY FIELD, with no cast. `writeGlobs` is REQUIRED on RoleCapability and OPTIONAL
    // on a floor — the packaged floors omit it whenever it is empty, so `worker` genuinely has no such
    // key. The `as Omit<RoleCapability, "role">` this replaced ASSERTED the required shape without
    // supplying it, handing `roleWriteRules` / `hasScopedWriteCarveOut` / `scopeWriteGlobs` an
    // `undefined` the type says cannot occur — and silencing the one check that would have said so.
    // Spelling the conversion out makes a missing required field a compile error instead.
    const f = persona.floor;
    return {
      role: persona.role,
      github: f.github, git: f.git, code: f.code, net: f.net, ui: f.ui,
      // `?? "read"` for the same reason `roleCapability` defaults it: a persona floor authored before
      // the `graph` axis shipped carries no value there, and an absent tier must read as the SAFE one
      // rather than as a grant nobody wrote down (`the-algorithms-graph-has-no-write-gate`).
      graph: f.graph ?? "read",
      writeGlobs: f.writeGlobs ?? [],
      harvestRoots: f.harvestRoots,
      allow: f.allow,
      ...override,
    };
  }
  const role = paneRole(s, paneId);
  return role ? roleCapability(role, override) : null;
}

/**
 * The LLM config a specific pane runs on: the global provider/key/endpoint, with this pane's own
 * model substituted when it has one.
 *
 * `paneModels[paneId]` is where the whole model precedence chain lands — `streamPaneWiring` writes a
 * fleet stream's model there, falling back to a team placement's and then the persona's default. For
 * a Claude pane the harness turns that into `claude --model <tier>`; for a local pane it has to
 * become `$BSC_AGENT_MODEL`, or the chain simply stops.
 *
 * A CLAUDE TIER IS NOT A LOCAL MODEL, and this is where that has to be caught. The tiers
 * (`haiku-4.5`/`sonnet-4.5`/`opus-4.5`) are Claude Code aliases; sending one to Ollama is a 404, not
 * a fallback. `resolveModel` already guards the neighbouring case — a stale `claude-*` id on a local
 * provider — but a TIER id does not start with `claude`, so it would sail through. A pane still
 * carrying a tier while the provider is local means nobody chose a local model for it, so the
 * configured one is the right answer.
 */
export function paneLlmConfig(s: AppStore, paneId: string): LlmConfig {
  const cfg = resolveLlmConfig(s);
  // Optional-chained for the same reason `sandboxPlanFor` optional-chains `paneWslDistro`: this runs
  // on the LAUNCH PATH, before anything guarantees the map is populated, and choosing a model must
  // not be the thing that throws. Caught by the carried tests, which build partial snapshots.
  const paneModel = s.paneModels?.[paneId];
  if (!paneModel || (MODEL_IDS as readonly string[]).includes(paneModel)) return cfg;
  if (providerNeedsBscAgent(cfg.provider)) return { ...cfg, model: paneModel };
  // #173: the CALLER only reaches `paneLlmConfig` once THIS pane's own harness is already "bsc-agent"
  // (`buildAgentEnv`'s `providerId === "bsc-agent"` gate) — `streamPaneWiring` sets that PER STREAM,
  // independently of the fleet-wide/global provider. So a non-tier `paneModel` surviving to here can
  // only be a local model name reached on a fleet whose global provider is still hosted (Claude/OpenAI/
  // Gemini). The global provider/key don't apply to this pane at all: route it at the configured local
  // endpoint instead of silently keeping the hosted provider's own model (the bug this pane exists to
  // catch — a `bsc-agent` process launched with `BSC_AGENT_PROVIDER=anthropic` and a Claude-tier model,
  // never the local one the stream was actually given).
  return { provider: "ollama", model: paneModel, apiKey: "", baseUrl: cfg.baseUrl.trim() || DEFAULT_LOCAL_BASE_URL, numCtx: cfg.numCtx };
}

/**
 * This pane's RESOLVED skills, as the payload both harnesses are fed from.
 *
 * Pre-resolved per pane at tab creation (the fleet/triage snapshot, `paneSkills`); an ad-hoc console
 * falls back to the global set, still honoring this pane's own override (#1056) and its skill groups.
 *
 * Extracted so the two harnesses cannot resolve DIFFERENT sets. Claude gets these written to
 * `.claude/skills` by `ensure_session_settings`; bsc-agent gets the same array as `$BSC_AGENT_SKILLS`
 * (see {@link buildAgentEnv}). They were never going to agree while only one of them had a resolver —
 * and for the whole life of that asymmetry the bsc-agent side resolved nothing at all.
 */
export function sessionSkillCfgs(s: AppStore, paneId: string) {
  const skillDefs = s.paneSkills[paneId]
    ?? effectiveSessionSkills(
         s.skills, "", s.sessionSkillOverrides[paneId],
         new Set(expandGroups(s.sessionSkillGroups[paneId] ?? [], s.skillGroups)),
       );
  return toSkillCfgs(skillDefs);
}

/** The capability the ACCESS env is gated on — `GH_TOKEN`, `BSC_HARVEST_ROOTS`, `BSC_STREAM`.
 *
 *  Exported so `pty_create` can be handed the SAME capability the env was built from
 *  (`the-launch-derives-its-own-access-env-instead-of-receiving-it`). One definition rather than two:
 *  if the view computed its own, the backend would gate on a capability the env was not built from,
 *  and a drift between them would surface as a removed credential with no explanation.
 *
 *  NOT the #3428 floor variant. This passes `writeGlobs` unconditionally, which is what
 *  `buildAgentEnv` has always done — the floor matters for the write-SCOPE, which is its own item
 *  (`the-launch-derives-its-own-write-scope-instead-of-receiving-it`); changing it here would be a
 *  behaviour change smuggled into a wiring change. */
export function paneAccessCapability(s: AppStore, paneId: string): RoleCapability | null {
  return paneCapability(s, paneId, { writeGlobs: s.paneRoleGlobs[paneId] ?? [] });
}

export function buildAgentEnv(
  s: AppStore,
  paneId: string,
  providerId: string,
  ghToken: string,
): Record<string, string> | undefined {
  const e: Record<string, string> = {};
  // The pane's role capability, resolved up-front: it gates both the write-scope env below AND whether
  // this session is handed a GitHub credential at all.
  const scopeRole = paneRole(s, paneId);
  const roleGlobs = s.paneRoleGlobs[paneId] ?? [];
  const scopeCap = paneAccessCapability(s, paneId);
  // GH_TOKEN carries gh / git-over-https auth. A role denied BOTH axes has no use for it: the app-owned
  // studio sessions (designer/librarian/architect — `none` on every axis, #3357) cannot run git or gh at
  // all, so placing a GitHub credential in the environment of the app's MOST restricted sessions would
  // widen them for nothing. Before #3357 these launched via a bespoke hook that passed no token; keep it
  // that way now that they run through the generic path. An ungated pane (no role) is unaffected, as is
  // any role with real git/gh access (a triage pane is `git:none` but `github:write`, so it keeps it).
  const noGitOrGithub = !!scopeCap && scopeCap.git === "none" && scopeCap.github === "none";
  if (ghToken && !noGitOrGithub) e.GH_TOKEN = ghToken;
  // Role-declared READ-only harvest roots (#3509). The ROLE names intent (`app-repo`) because a role is
  // machine-independent; the launch resolves it to a real path. This widens only what `bsc ui harvest`
  // / `bsc graph harvest` may SCAN — it grants no write anywhere, which is the point: the designer is
  // `code: none` with `scratch/**` its only writable glob, yet must be able to mine the app's own UI
  // (#3451/#3471). A token that resolves to nothing contributes nothing, mirroring the CLI's rule that
  // an unresolvable allow-list entry is skipped rather than widening access.
  const harvestRoots = (scopeCap?.harvestRoots ?? [])
    .map((token) => {
      if (token === HARVEST_ROOT_APP_REPO) return s.appRepoRoot;
      // The whole downloaded-repos tree (#3664), resolved to `<base>/projects` — read-only, so the
      // designer can mine other repos' UI. An empty `bscBaseDir` (pre-hydration) contributes nothing.
      if (token === HARVEST_ROOT_PROJECTS) return s.bscBaseDir ? `${s.bscBaseDir}/projects` : null;
      return null;
    })
    .filter((p): p is string => !!p);
  // Newline-separated to match the CLI parser (a Windows path contains both `;` and a `:`).
  if (harvestRoots.length) e.BSC_HARVEST_ROOTS = harvestRoots.join("\n");
  // Write-scope gate (#1297): hand the session its allowed write globs so the `bsc-scope`
  // PreToolUse hook hard-blocks any write outside them — the hard deny the role gate's
  // allow-only rules lack. Applies to every gated pane.
  if (scopeRole && scopeCap) {
    const sg = scopeWriteGlobs(scopeRole, roleGlobs);
    if (sg.length > 0) {
      e.BSC_SCOPE_GLOBS = sg.join(" ");
    } else if (scopeCap.code === "none") {
      // code:none with no write globs ⇒ DENY ALL writes (#1916 Step 3.5). The sentinel makes bsc-scope
      // hard-block every Edit/Write — surviving bypassPermissions, where the role's permissions.deny
      // write rule is ignored. (A code:none role WITH globs — e.g. a director's commons — is scoped
      // above; an ungated pane has no scopeRole, so it stays allow-all.)
      e.BSC_SCOPE_GLOBS = SCOPE_DENY_ALL;
    }
    // Store scopes (#2470, defense-in-depth): the role's per-store access tiers (currently just `ui`)
    // for the store CLIs — `bsc ui` refuses its mutating verbs when scoped read-only. Guards accidents
    // + non-Claude runtimes; the launch-time deny rules (sessionDeniedCommands) are the boundary.
    e.BSC_SCOPES = JSON.stringify(sessionScopes(scopeCap));
  }
  // Deny-list (#1916): the session's role/user/profile deny patterns for the `bsc-deny` PreToolUse
  // hook (newline-separated; the dangerous floor itself is compiled into `bsc hook bash-deny`). This
  // carries the role/user denies through the bypassPermissions flip.
  const denies = sessionDeniedCommands(s, paneId);
  if (denies.length > 0) e.BSC_DENY_BASH = denies.join("\n");
  // Per-stream plan scoping (#3279): a WORKER pane owns exactly one fleet stream, so scope its
  // `bsc plan` to that stream — it reads + touches only its own issues (the plandb CLI enforces it).
  // `fleetPaneStreams[paneId]` is set only for worker panes at fleet launch; coordinating roles
  // (director/planner/triage/reviewer/…) get NO $BSC_STREAM and keep full cross-stream access, which
  // they need to integrate + judge. Gate on the worker role too, so a non-worker stream pane (a
  // reviewer/juror that judges another stream's landing) isn't accidentally boxed into its own.
  const streamId = s.fleetPaneStreams[paneId]?.id;
  if (streamId && paneRole(s, paneId) === "worker") {
    e.BSC_STREAM = streamId;
    // …and which FEATURE's records it may WRITE (`a-worker-writes-only-its-own-feature`).
    //
    // The same gate one level finer: `$BSC_SCOPES` says whether this session writes the graph stores
    // at all, this says which of their records. Without it a worker granted `graph: write` could still
    // rewrite `core` — 204 algorithm records and 154 components that every other feature composes.
    //
    // Derived from the stream, never stamped separately, so the confinement and the prerequisite block
    // (`inject_required_algorithms`, which resolves the same stream to the same feature) can never
    // disagree about which lane a worker is in. A stream naming no feature falls back to its own id,
    // exactly as the launch does — 37 of studio-code's 89 stream ids ARE feature slugs.
    //
    // WRITES ONLY. A feature's `requires` deliberately names records it does NOT own, so bounding
    // reads would make a worker's own prerequisites unreadable — the precise opposite of the point.
    const feature = (s.fleetPaneStreams[paneId]?.feature ?? "").trim() || streamId;
    e.BSC_FEATURES = feature;
  }
  if (providerId === "bsc-agent") {
    // The pane's own model wins over the globally-configured one (#the-director-chooses…).
    //
    // The precedence chain — a fleet stream's model > a team placement's > the persona's default >
    // the harness's default — was already built and already documented on `bsc teams model` /
    // `bsc persona model`, and `streamPaneWiring` already routes a stream's model into `paneModels`.
    // It then DIED here: `BscAgentAdapter.model_flag` returns None (the model is env-selected, not a
    // CLI flag) and this line filled BSC_AGENT_MODEL from the GLOBAL `llmModel`, so every local
    // worker ran the one model in Settings no matter what the director had assigned.
    Object.assign(e, bscAgentEnv(paneLlmConfig(s, paneId)));
    // Gate the runtime by the pane's role (least-privilege parity with Claude); no role ⇒ permissive.
    const bscRole = paneRole(s, paneId);
    if (bscRole) {
      const cap = paneCapability(s, paneId, { writeGlobs: s.paneRoleGlobs[paneId] ?? [] })!;
      // Reconcile role ↔ flow (#304): the flow owns git push / gh pr create, so lift them from
      // the role denies when it permits pushing/PRing.
      const granted = flowGrantedPushCommands(s.paneFlows[paneId]);
      // THE USER'S OWN DENYLIST RIDES IN HERE, and for years it did not
      // (`a-bsc-agent-session-never-gets-the-users-denylist`). `bscAgentPerms`' own doc says why it
      // must: bsc-agent has no `.claude/settings.json` for the user's list to ride in on, so this
      // document is the only route. The argument defaults to `[]` and this call passed two, so a
      // command the user denied in Settings was enforced on Claude and not on the local harness —
      // and there is no second route, since `Permissions::from_env` reads no `$BSC_DENY_BASH`.
      //
      // The SAME store field the Claude path sends as `userDeniedCommands`, so the two harnesses deny
      // one list rather than two restatements of it.
      // …and the SURFACE COMPLEMENT, which this call omitted
      // (`a-bsc-agent-session-is-denied-less-than-the-same-role-on-claude`). The same catalog the
      // Claude path passes through `sessionDeniedCommands`, so a persona's undeclared `bsc` surfaces
      // are denied on both harnesses rather than only on one.
      e.BSC_AGENT_PERMS = JSON.stringify(
        bscAgentPerms(cap, granted, s.deniedCommands, deniableSurfaceNames(s.surfaceCatalog)),
      );
    }
    // MCP: pass the resolved stdio servers so bsc-agent's client connects them ($BSC_AGENT_MCP).
    const { mcp } = toSessionPayloads(resolvePersonaMcp(s.mcpServers, paneMcpIds(s, paneId)), []);
    const bscMcp = toBscAgentMcp(mcp);
    if (bscMcp.length > 0) e.BSC_AGENT_MCP = JSON.stringify(bscMcp);
    // Skills: hand over this pane's RESOLVED set the same way MCP and perms go over.
    //
    // A bsc-agent session got NONE before this. The only writer of `.claude/skills` is
    // `write_session_skills`, reached from the `ensure_session_settings` command — and TerminalView
    // calls that only for a CLAUDE pane (`launchesClaude` requires `isClaudeProvider`). So the runtime
    // scanned a directory nothing had ever created for it, found nothing, and looked exactly like a
    // session that legitimately had no skills attached.
    //
    // Note this is the PER-PANE resolved set, which is strictly more than a worker already had: a fleet
    // worker did receive the hub's blueprint `skills.md`, inlined into `CLAUDE.local.md` by
    // `ensure_worktree`, but never its session overrides, its skill groups, or its PERSONA's skills.
    // A director / triage / manual bsc-agent pane received nothing at all.
    const skillCfgs = sessionSkillCfgs(s, paneId);
    if (skillCfgs.length > 0) e.BSC_AGENT_SKILLS = JSON.stringify(skillCfgs);
  }
  if (providerId === "aider") {
    // Aider (#1172): inject the provider's API key env (ANTHROPIC_/OPENAI_/GEMINI_API_KEY, or an
    // OPENAI_API_BASE for a local/ollama OpenAI-compatible endpoint) so the `--model` selected in
    // `buildAiderCommand` can actually reach the configured LLM. GH_TOKEN (added above) lets an Aider
    // worker push + open its PR, exactly like the other providers.
    Object.assign(e, aiderEnv(resolveLlmConfig(s)));
  }
  return Object.keys(e).length > 0 ? e : undefined;
}

/**
 * The per-provider launch config handed to a non-Claude provider's `buildLaunchCmd`. Only Aider
 * (#1172) needs one today: it maps the pane's resolved LLM config, its startup prompt, and a worker's
 * `CLAUDE.local.md` scope into `aider --model … --read … --message …`. Every other provider ignores
 * the config (returns undefined so they launch unchanged).
 */
export function providerLaunchConfig(
  s: AppStore,
  paneId: string,
  provider: ConsoleProvider,
  startupPrompt: string | undefined,
): ProviderLaunchConfig | undefined {
  if (provider.id !== "aider") return undefined;
  return {
    llm: resolveLlmConfig(s),
    startupPrompt: startupPrompt && startupPrompt.trim() ? startupPrompt : undefined,
    // A worker's plan scope (CLAUDE.local.md, copied into the worktree by ensure_worktree) — handed to
    // Aider read-only since it does no ancestor-CLAUDE.md walk. Only workers have one.
    readFiles: paneRole(s, paneId) === "worker" ? ["CLAUDE.local.md"] : undefined,
  };
}

/**
 * The session's denied Bash command patterns (#1916): the user's global denies + the role's denied
 * commands (minus the pushes the flow grants back) + the profile's denies. The SINGLE source for both
 * the `permissions.deny` rules (buildSessionSettings) and the `$BSC_DENY_BASH` env the `bsc-deny`
 * PreToolUse hook enforces — so role/user denies survive `bypassPermissions`, where `permissions.deny`
 * is ignored but the hook still fires + blocks.
 */
export function sessionDeniedCommands(s: AppStore, paneId: string): string[] {
  const profileId = s.paneProfiles[paneId];
  const profile = profileId ? s.agentProfiles.find((p) => p.id === profileId) : undefined;
  const prof = profile ? resolveProfileSettings(profile) : null;
  // A GRANTED SURFACE IS A DECLARED SURFACE. The undeclared-surface complement below was built from
  // the ROLE alone, while a per-pane profile can grant a surface the role cannot name — the surface
  // operator's noun is chosen per SESSION, so no static role could ever declare it. The result was a
  // rendered settings file carrying `Bash(bsc studio *)` in BOTH allow and deny, and deny wins: the
  // one command that session exists to run was denied by the same change that granted it.
  //
  // Folding the profile's own surfaces in closes that. It cannot WIDEN anything a profile did not
  // already auto-approve, because it reads the very commands that are already in `allowedCommands`.
  const profileSurfaces = surfacesFromAllow(prof?.allowedCommands ?? []);
  const cap = paneCapability(s, paneId, {
    writeGlobs: s.paneRoleGlobs[paneId] ?? [],
    ...(profileSurfaces.length
      ? { surfaces: [...(capabilitySurfaces(paneCapability(s, paneId) ?? undefined) ?? []), ...profileSurfaces] }
      : {}),
  });
  const granted = flowGrantedPushCommands(s.paneFlows[paneId]);
  // `s.surfaceCatalog` is the `bsc` surface catalog (`a-persona-declares-its-command-surfaces`).
  // Passing it here is what turns a persona's DECLARED surface set into real denies: every catalog
  // surface the role did not name becomes `bsc <s>`, which reaches `permissions.deny` AND
  // `$BSC_DENY_BASH` — so it holds under the bypass posture too, where `permissions.deny` is ignored.
  //
  // `deniableSurfaceNames`, not the band's active-only list: a DEPRECATED alias serves the same store
  // as its live surface (`bsc org` → the teams store, `bsc component` → the component library), so
  // leaving it out of the complement would keep a side door open into a store the declaration closed.
  //
  // An EMPTY catalog (the poll has not resolved, or it failed) denies nothing extra, by design. A
  // launch that races the read must not lose its whole CLI; see `roleDeniedCommands`.
  const roleDenies = (cap ? roleDeniedCommands(cap, deniableSurfaceNames(s.surfaceCatalog)) : []).filter((d) => !granted.includes(d));
  return [...s.deniedCommands, ...roleDenies, ...(prof?.deniedCommands ?? [])];
}

/**
 * The permission + extension payload for `ensure_session_settings` (everything except `cwd` and
 * `replacePermissions`, which the caller adds). Composes the role gate (#219), the per-agent profile
 * (#255), the per-agent flow (#297/#304), resolved MCP servers + hooks, skills (#636), and the audit
 * /confine/scope/taint/defer/skill/activity hooks. Spread the result straight into the invoke args.
 *
 * @param s       store snapshot taken at the settings-composition point
 * @param paneId  the pane being launched
 */
/** Drop the MCP servers a session in a mount namespace provably cannot spawn.
 *
 *  The BUILT-IN servers (Research, Compliance, the marketer's channel mock) carry a marker command
 *  that the Rust side rewrites to the bundled `bsc` binary's absolute HOST path. Inside the cage
 *  `$HOME` is `/home/agent` and that path does not exist — `bsc` is deliberately not bound, because
 *  binding the umbrella would put DuckDB and a writable store inside the isolation. So every caged
 *  launch declared two servers in `.mcp.json`, listed them in `enabledMcpjsonServers`, and both
 *  failed to spawn. Measured: a director rebuilt from its real launch argv reported exactly that.
 *
 *  Only the built-ins are dropped, and only under a namespace. A repo-authored stdio server can
 *  legitimately work in the cage — `node ./scripts/mcp.js` spawns fine, since `node` is bound for a
 *  Claude session and the script lives under `/repo` — and an http server needs no binary at all.
 *  Dropping every stdio server would remove those working cases to fix a knowably broken one.
 *
 *  An absent capability an agent is told about costs nothing; an advertised one that fails is spent
 *  on retries and misdiagnosis. */
export function mcpReachableFrom<T extends { id: string }>(servers: T[], sandboxed: boolean): T[] {
  if (!sandboxed) return servers;
  const builtin = new Set(BUILTIN_MCP_SERVERS.map((b) => b.id));
  return servers.filter((e) => !builtin.has(e.id));
}

export function buildSessionSettings(s: AppStore, paneId: string, sandboxed = false) {
  // Role gate (#219): a planner/worker/triage session has its mutating git/gh commands denied at
  // launch (deny > the broad gh/git allow), plus a write-tool guard (#238). Absent role ⇒ unrestricted.
  const role = paneRole(s, paneId);
  // The worker's write boundary (its owned globs) makes roleWriteRules auto-approve Edit/Write within
  // its lane; without it a worker (code:write, empty writeGlobs) prompts on every edit.
  //
  // The empty case must FLOOR to the role table rather than override it (#3428) — `roleCapability` is a
  // plain spread, so passing `{ writeGlobs: [] }` REPLACES the role's own default boundary. `paneRoleGlobs`
  // is a fleet concept (only `fleetStartProject` writes it), so every non-fleet pane arrives here empty:
  // that erased the restricted studios' `scratch/**` carve-out (#3373), collapsing `hasScopedWriteCarveOut`
  // to false and denying the bare write tools — leaving a designer unable to stage the payload file that
  // `bsc ui set --file` exists to read. Mirrors `scopeWriteGlobs` (writeScope.ts), which floors it the same
  // way so the launch settings and the bsc-scope hook agree on one boundary.
  const roleGlobs = s.paneRoleGlobs[paneId] ?? [];
  const cap = paneCapability(s, paneId, roleGlobs.length ? { writeGlobs: roleGlobs } : {});
  const write = cap ? roleWriteRules(cap) : { allow: [], deny: [] };
  // Agents gate (#255): the profile assigned to this pane is the SOLE source of auto-approved
  // commands (#1457), plus its per-tool/path rules, on top of the role gate (deny wins for both).
  const profileId = s.paneProfiles[paneId];
  const profile = profileId
    ? s.agentProfiles.find((p) => p.id === profileId)
    : undefined;
  const prof = profile ? resolveProfileSettings(profile) : null;
  // Per-agent flow (#297): narrow the GitHub-propagation writes per the stream's push policy + gate.
  const paneFlow = s.paneFlows[paneId];
  const flowRules = flowPermissionRules(paneFlow);
  // The role's fixed store-CLI surface (#3095): a curator pane always auto-runs `bsc ui`/`bsc graph`
  // (its harvest + graph-optimize channels) whether or not a profile assigned them. Empty for every
  // other role, so this is a no-op elsewhere.
  const restrictedCommands = restrictedRoleCommands(role);
  const allowedCommands = [...(prof?.allowedCommands ?? []), ...restrictedCommands];
  // Tighten a role with a fixed store surface to `restrictedAllow` (#3098): suppress the Bash baseline
  // tiers entirely (git/build/read-only), so the curator's WHOLE auto-run command surface is exactly
  // the two store CLIs above — mirroring the standing-tab designer/librarian/architect. Bash-only:
  // the verbatim tool rules (Read/Edit/…) still apply, so `Read` (added below) keeps the curator able
  // to read generated source to `bsc ui set` it.
  const restrictedAllow = restrictedCommands.length > 0;
  // Shell posture (#1572): the profile's bash tier scales the backend's auto-approve baseline.
  // No profile ⇒ the broad default ("allow").
  const bashPosture = prof?.bashPosture ?? "allow";
  // Denied commands (#304/#1916): user + role (minus the flow-granted pushes) + profile denies — the
  // SAME set wired into `$BSC_DENY_BASH` for the bsc-deny hook (see sessionDeniedCommands).
  const denied = sessionDeniedCommands(s, paneId);
  // A restricted role (#3098) suppresses the Bash baselines, so grant the `Read` tool explicitly —
  // the curator reads generated component source before harvesting it via `bsc ui set`. Mirrors the
  // designer hook's `[...write.allow, "Read"]`. The backend dedupes, so a redundant Read is harmless.
  const allowToolRules = [...write.allow, ...(prof?.allowToolRules ?? []), ...(restrictedAllow ? ["Read"] : [])];
  // Confinement self-protection (#1916): the agent must not disable the FS-confinement hook or its own
  // permission set by editing them. Deny file writes on `.claude/**` — the in-repo config the
  // bsc-confine hook itself can't catch (it only blocks paths OUTSIDE the repo root). The app stays
  // authoritative regardless (it re-writes `.claude/settings.json` at every launch). On EVERY pane.
  // ONE `Edit(.claude/**)` rule (#3534): Claude Code matches file-permission rules on the Edit tool
  // alone and it covers every file-editing tool — the former `Write/MultiEdit/NotebookEdit(.claude/**)`
  // rules were NEVER enforced (MultiEdit is not even a tool), so this deny was silently a no-op.
  const confinementConfigDeny = [editPathRule(".claude/**")];
  // Worker sub-agent block (#1036): deny the Task tool for workers. Deny wins over any profile allow.
  const denyToolRules = [...confinementConfigDeny, ...write.deny, ...(cap ? roleDeniedTools(cap) : []), ...(prof?.denyToolRules ?? []), ...flowRules.denyToolRules];
  const askToolRules = flowRules.askToolRules;
  // MCP servers + hooks resolved for this session — pre-resolved per pane at tab creation; fall back
  // to globals for ad-hoc consoles.
  const mcpServers = mcpReachableFrom(resolvePersonaMcp(s.mcpServers, paneMcpIds(s, paneId)), sandboxed);
  const hookDefs = resolvePersonaHooks(panePersona(s, paneId)?.hooks);
  const { mcp, hooks } = toSessionPayloads(mcpServers, hookDefs);
  const skills = sessionSkillCfgs(s, paneId);
  // Agents audit (#257): on a gated pane (role or profile assigned), install PreToolUse hooks: log
  // each tool attempt (bsc-audit), time MCP calls (bsc-mcp), enforce the write-scope gate (bsc-scope,
  // #1297) and the tainted-turn gate (bsc-taint, #1167). FS confinement (bsc-confine, #158) is NOT
  // gated — it's defaulted onto every pane below (#1916).
  //
  // NO SESSION GETS A STOP BOUNCE ANY MORE (#session-stop-is-honoured). A worker used to carry
  // `bsc-defer` (#369) here — a Stop hook that REFUSED the stop and sent it back to work. #4021 widened
  // it from bouncing once to bouncing while any work remained, and the measured result was a session
  // that could not end: one worker emitted `maintain` 66 times on a ~90s cadence, trying to stop and
  // being pushed back each time. `maintain` became the most common event in the whole coordination log.
  //
  // Nothing was polling to wake those sessions; they were PREVENTED FROM STOPPING, which looks identical
  // from outside — which is why two separate sweeps of the app's injection sites missed it. Resuming a
  // finished session is the user's click now, so the hook has no successor: the comment above used to
  // say "it bounces ONCE per stop, so a finished worker is never trapped", and that stopped being true
  // in #4021 without the comment changing, which is most of why it survived review.
  //
  // The restricted STUDIO sessions never had one (#3580) — their keep-going is the LOOP pump
  // (useDesignerLoopPump, #3292), which drives a session turn-by-turn ONLY while an open loop exists.
  // That remains the one sanctioned way a session is kept going, and it is bounded by an explicit loop.
  // A fleet WORKER also gets the superseded gate (bsc-superseded, #4240): two actors can land the same
  // issue — a director closes one directly, two streams overlap — and today the second worker finds out
  // at MERGE time, after writing code and opening a conflicting PR. The completion is already ON the
  // coordination wire (`bsc-landed`/`merged`/`closed`, each pane-tagged); it was just never delivered
  // back INTO a session. This reads it before an edit and blocks ONCE per issue, then latches — so the
  // worker is informed and moves on. Worker-only: a director coordinating is not doing the work.
  const workerGates = role === "worker"
    ? [{ event: "PreToolUse", matcher: "Edit|Write|MultiEdit|NotebookEdit", command: "bsc-superseded" }]
    : [];
  const gatedHooks = (cap || prof)
    ? [...hooks,
       { event: "PreToolUse", matcher: "", command: "bsc-audit" },
       { event: "PreToolUse", matcher: "mcp__.*", command: "bsc-mcp" },
       { event: "PostToolUse", matcher: "mcp__.*", command: "bsc-mcp" },
       { event: "PreToolUse", matcher: "Edit|Write|MultiEdit|NotebookEdit", command: "bsc-scope" },
       { event: "PreToolUse", matcher: "", command: "bsc-taint" },
       // Supply-chain add gate (bsc-supply, #3799): block an install that ADDS a malicious/known-vulnerable
       // dependency (OSV via `bsc cve`). GATED (agent panes only) — the threat is compromised agents, not
       // the maintainer's manual console — and FAIL-OPEN, so an OSV outage never blocks the fleet.
       { event: "PreToolUse", matcher: "Bash", command: "bsc-supply" },
       // Fork visibility (bsc-fork, #4106): a subagent is the ONE actor in this system with no pane,
       // no roster row, no worktree and no branch — so a director that forks to do a worker's job does
       // it entirely off the coordination channel. `audit.log` already records the call, but nothing
       // reads that channel; this puts the fork where the inbox and Glance are looking. OBSERVE ONLY —
       // it always exits 0. The boundary on what a fork may do is the role gate (a director is
       // `code: none`), not this hook; making forks legible is a separate job from restricting them.
       { event: "PreToolUse", matcher: "Agent|Task", command: "bsc-fork" },
       ...workerGates]
    : hooks;
  // Skill telemetry (#406) follows the SKILLS, not the role gate: install the bsc-skill Pre/Post hooks
  // whenever skills are present (incl. an ungated console with a per-session skill, #1056).
  const skillHooks = skills.length > 0
    ? [...gatedHooks,
       { event: "PreToolUse", matcher: "Skill", command: "bsc-skill" },
       { event: "PostToolUse", matcher: "Skill", command: "bsc-skill" }]
    : gatedHooks;
  // Turn-activity hooks (#1184): authoritative turn boundaries for the status dot, on EVERY
  // claude-launching pane. Ordering no longer matters here — the Stop bounce that used to precede
  // these is gone, so nothing can block the stop before the accounting hooks record it.
  const sessionHooks = [
    ...skillHooks,
    // FS confinement (#158/#1916): the DEFAULT, un-gated deny — confine the AI's file tools to this
    // session's repo root ($BSC_REPO_ROOT, set per-pane in pty_create) on EVERY claude-launching pane,
    // role/profile or not. The deny every session starts with; the OS sandbox (WSL2/Seatbelt) extends
    // the same boundary to Bash (the one tool a PreToolUse hook can't fully confine).
    { event: "PreToolUse", matcher: "Edit|Write|MultiEdit|NotebookEdit|Read", command: "bsc-confine" },
    // Dangerous-command floor (#1916): the DEFAULT deny — `bsc-deny` hard-blocks (exit 2) any Bash
    // command hitting the shared dangerous floor (`bsc_util::dangerous`), enforced via the `bsc`
    // binary so it survives `bypassPermissions` (where `permissions.deny` is ignored but PreToolUse
    // hooks still fire+block). The foundation the deny-list switch builds on; reads `$BSC_DENY_BASH`
    // for the per-session role/user denies wired in at the bypass flip.
    { event: "PreToolUse", matcher: "Bash", command: "bsc-deny" },
    // Turn accounting (bsc-activity + bsc-tokens, #1184/#416) — the un-gated observability floor, from
    // the ONE shared constant every launch path spreads (#3452 fleet / #3455 planner both silently lost
    // this set when it was inlined per-path). bsc-tokens is the ONLY per-session token source, so it
    // must fire on Stop, and now nothing can refuse that Stop — these are the only Stop hooks left.
    ...TURN_ACCOUNTING_HOOKS,
  ];
  return {
    // THE PROFILE ITSELF, so the backend can DERIVE the bridge it currently only obeys
    // (`the-launch-derives-the-profile-settings-instead-of-receiving-them`). `bashPosture` is why this
    // matters most: `build_allow_rules` scales the WHOLE auto-approve baseline by it, so until now the
    // breadth of a session's shell surface was decided in this renderer and obeyed unchecked.
    //
    // The four derived fields below STAY on the payload — this is a dual run, not a cut. Rust unions
    // its derivation with them and WARNs on anything it derived that they omitted, and the TypeScript
    // is deleted in its own slice once that warning has been empty in the field. `null`, not omitted,
    // for a pane with no profile: there is nothing to derive and the backend passes everything through.
    agentProfile: profile ?? null,
    // THE ROLE ITSELF, and the two lists the backend's derivation needs alongside it
    // (`the-role-gate-flip-never-reached-the-wire`). `ensure_session_settings` has ACCEPTED
    // `roleCapability`/`activeSurfaces` since the role-gate cutover and nothing ever sent them, so
    // `reconcile_role_denies` and `reconcile_tool_rules` took the `None` branch on every real launch
    // and the WARN that was supposed to end the transition could not fire.
    //
    // `flowGrantedCommands` is NEW and is what makes turning the rest on safe. The role gate denies
    // `gh pr create` for a worker (`github: read`) and the FLOW is the authority over that and
    // `git push` (#304) — `sessionDeniedCommands` subtracts them below. Without the same subtraction
    // on the backend, the union would add both straight back and no auto-pr worker could open its PR.
    roleCapability: cap,
    // The RAW catalog, not the filtered names. `deniableSurfaceNames` is ported
    // (`denies::deniable_surface_names`), so sending its output was this side answering a question
    // the backend can answer — the same call as `flowPush` below. The filter is not cosmetic: a
    // DEPRECATED alias serves the same store as its live surface (`bsc org` → the teams store), so
    // dropping it from the complement keeps a side door open into a store the declaration closed.
    surfaceCatalog: s.surfaceCatalog,
    // The flow's PUSH POLICY and the user's OWN denylist — the two inputs the backend's deny
    // composition cannot derive (`the-launch-composes-its-own-denies-instead-of-receiving-them`).
    //
    // The policy REPLACED a `flowGrantedCommands` list: `denies::flow_granted_push_commands` is the
    // ported rule, so sending its output was sending a computed answer, and the absent-flow default
    // now lives in exactly one place. It used to be `auto-pr`, which meant a fleet on untouched
    // defaults pushed branches regardless of intent — a second copy is where that comes back.
    //
    // The user's list is the one source derived from nothing, which is why it has to travel: the
    // backend would otherwise compose a list that silently dropped it.
    flowPush: paneFlow?.push,
    userDeniedCommands: s.deniedCommands,
    // The PANE ID, the flow's GATE and the global bypass toggle — the last three inputs the backend's
    // permission block needs and cannot derive
    // (`the-launch-composes-its-own-tool-rules-instead-of-receiving-them`).
    //
    // The pane id is what `isFullCapabilitySession` reads: the debug studio is always bypass, BY
    // DEFINITION, and that arm has to survive a reconciliation whose rule is otherwise "the
    // restrictive value wins". It does, because both sides derive it from this same id.
    //
    // `bypass` below still travels: the backend composes its own and takes the RESTRICTIVE value on a
    // disagreement, since bypass decides whether `permissions.deny` is honoured at all — prompting
    // less than intended is a hole, prompting more is a complaint.
    paneId,
    flowGate: paneFlow?.gate,
    globalBypass: s.bypassPermissions,
    // The PERSONA's own hooks, and whether `hooks` above is the sandboxed substitution
    // (`the-launch-composes-its-own-hook-chain-instead-of-receiving-it`). The backend composes the
    // rest of the chain around the persona's — persona resolution is the renderer's job, the same
    // way the surface catalog above is — and unions the result with `hooks`, warning on anything it
    // did not compose. It can never produce a SHORTER chain: an unregistered hook does not error, it
    // just never fires, which is how bsc-tokens went missing for three weeks (#3452) and how the
    // planner ran with no hooks at all (#3455).
    //
    // `namespaceHooks` is what stops the backend composing OVER the sandbox substitution and
    // silently undoing it; that swap belongs to the sandbox cluster and stays here.
    personaHooks: hooks,
    namespaceHooks: sandboxed,
    // The per-session SKILL facts, so the backend can resolve the set instead of receiving it
    // (`the-launch-resolves-its-own-skills-instead-of-receiving-them`). The LIBRARY is not among
    // them: `crates/skilldb` IS the store and Rust reads it directly, the same way it reads the
    // studio registry and the write-locks file.
    //
    // `skillProjectId` is `""` because that is what `sessionSkillCfgs` passes — so project-SCOPED
    // skills never apply on either side today. Reproduced rather than corrected: making them apply
    // would change which skills a session gets, which is a behaviour change and not this flip.
    //
    // `skillsExplicit` says the pane carries a hand-set list (`paneSkills`) that short-circuits
    // resolution. The backend defers to it rather than unioning, because unioning against an
    // explicit choice would add skills the user did not choose — and would fire the divergence
    // warning on every such pane, which is how a signal becomes noise.
    skillProjectId: "",
    skillOverride: s.sessionSkillOverrides[paneId],
    skillGroupIds: s.sessionSkillGroups[paneId] ?? [],
    skillsExplicit: s.paneSkills[paneId] !== undefined,
    // The MCP server LIBRARY and this pane's persona carries. Unlike the skills library this one is
    // NOT backend-owned — `s.mcpServers` is store state with no Rust store behind it — so it travels
    // (`the-launch-resolves-its-own-mcp-servers-instead-of-receiving-them`). The BUILT-INS do not:
    // the backend reads the same `mcp/builtin-servers.json` overlay this side does.
    mcpLibrary: s.mcpServers,
    personaMcpIds: paneMcpIds(s, paneId),
    allowedCommands,
    deniedCommands: denied,
    mcpServers: mcp,
    // A namespace session gets the subset it can actually run (see SANDBOXED_HOOKS). Defaulting
    // `sandboxed` to false keeps every existing caller byte-identical.
    hooks: sandboxed ? SANDBOXED_HOOKS : sessionHooks,
    allowToolRules,
    denyToolRules,
    askToolRules,
    skills,
    bashPosture,
    // Restricted allow-list (#3098): when set, `build_allow_rules` emits ONLY the wrapped
    // allowedCommands — no Bash baselines/mandatory tier. True only for a role with a fixed store
    // surface (curator today); false-y leaves the normal posture-scaled baselines intact.
    restrictedAllow,
    // Permission posture (#1916): bypass=true ⇒ deny-list (auto-run; the PreToolUse hooks gate); false ⇒
    // allow-list (Claude's `default` mode — require approval). User-toggled in Settings; default true.
    // Two role/session-derived carve-outs override the global toggle in OPPOSITE directions:
    //   • A full-capability app-owned session (the DEBUG session, #3326) is ALWAYS bypass — it's the
    //     unrestricted maintenance session by definition (preserves its old bespoke posture).
    //   • A RESTRICTED role (designer/librarian/architect/curator) is NEVER bypass: bypass auto-runs
    //     everything and ignores `permissions.deny`, which would hand a session deliberately confined to
    //     its store CLI (the designer is `bsc ui`-only) a general shell. The confinement travels with the
    //     role, so it holds on every launch path.
    bypass: isFullCapabilitySession(paneId) ? true : isRestrictedRole(role) ? false : s.bypassPermissions,
  };
}

/**
 * Resolve the effective `init_cmd` for `pty_create`.
 * - Claude panes: explicit initCmd wins, then the startup-prompt baking path (pty_create handles it —
 *   don't also inject an init_cmd), then ad-hoc auto-resume (`claude --continue`). Manual consoles are
 *   never auto-recovered (#1176) — their crash-resume signals are suppressed.
 * - Non-Claude providers: explicit initCmd wins; otherwise the provider's own launch command.
 *
 * @param s        store snapshot taken at the init-cmd resolution point
 * @param paneId   the pane being launched
 * @param isClaudeProvider  whether the resolved provider is Claude
 * @param initCmd  the pane's explicit init command, if any
 * @param startupPrompt  the composed startup prompt, if any (drives the baking path)
 * @param provider the resolved provider (for its `buildLaunchCmd`)
 */
export function resolveEffectiveInitCmd(
  s: AppStore,
  paneId: string,
  isClaudeProvider: boolean,
  initCmd: string | undefined,
  startupPrompt: string | undefined,
  provider: ConsoleProvider,
): string {
  const manual = isManualPaneId(paneId);
  // WHICH HARNESSES RESUME, not "is this Claude" (`a-resuming-bsc-agent-pane-launches-a-new-conversation`).
  //
  // This read `isClaudeProvider`, and `bsc-agent` declares `isClaude: false` — so a resuming local
  // worker fell to the branch below, which returns its `initCmd` verbatim. That value is the BARE
  // HARNESS NAME (`fleetStartProject` writes `paneInitCmds[paneId] = w.provider ?? …`), so it launched
  // a fresh `bsc-agent` beside the conversation it meant to rejoin. `resolveInitCmd` derives the resume
  // form from the placeholder precisely so that cannot happen (#173) and was unreachable for the one
  // harness that needed it.
  //
  // A UNION, not a replacement, and that is deliberate. `isClaudeProvider` still routes on its own:
  // a harness flagged `isClaude` belongs to this rule whether or not its id is a bare-name
  // placeholder, and keeping it means no pane that reaches `resolveInitCmd` today stops reaching it.
  // The change is purely ADDITIVE — `bsc-agent` joins — which is the shape a bug fix on the launch
  // path should have.
  if (isClaudeProvider || harnessResumes(provider.id)) {
    return resolveInitCmd({
      explicit: initCmd,
      startupPrompt,
      // #3928: the fleet/triage resume flag — a manual console never sets it, so #1041's
      // "a clean quit does NOT auto-resume" stays intact for those.
      // #3934: optional-chained — this sits directly on the pane-launch path, where a missing map
      // does not degrade the launch, it ABORTS it. The real store always populates both; a caller
      // holding a partial slice used to throw here before the launch command was ever resolved.
      continueSession: manual ? false : !!s.paneContinue?.[paneId],
      paneWasClaude: !!s.paneWasClaude?.[paneId],
      autoResumeClaude: manual ? false : s.autoResumeClaude,
      // Crash recovery (#1041): resume only after an unclean shutdown (silent, if opted in) or a
      // banner "restore" click — never on a clean restart, and never for a manual console.
      wasUncleanShutdown: s.uncleanShutdown,
      restoreRequested: manual ? false : !!s.restoreRequested[paneId],
    });
  }
  // Non-Claude: an explicit initCmd wins; otherwise the provider builds its own launch command from
  // the per-provider config (Aider maps LLM/model/prompt/worker-scope → flags, #1172; others ignore it).
  if (initCmd && initCmd.length > 0) return initCmd;
  return provider.buildLaunchCmd(providerLaunchConfig(s, paneId, provider, startupPrompt));
}

/**
 * Whether a Claude pane's baked startup prompt must be SUPPRESSED when it resumes a prior
 * conversation on a crash-restore remount (#2052). Keyed off the transient per-pane
 * `restoreRequested` flag set by `restoreSessionsFromCrash` — so it is true ONLY on the
 * crash-recovery relaunch, never on an intentional launch (a fresh triage/fleet kickoff, a
 * manual console, or a tab-switch reconnect all leave it false, so their prompts deliver as
 * usual). The backend's `fresh_only` only bites when the resumed session actually has history
 * (`fresh_only && has_history`), so a prompt still fires on a genuinely fresh launch.
 *
 * Without this, the crash-restore remount re-bakes the pane's persisted startup prompt /
 * checkpoint note as `claude --continue`'s initial message, which Claude then SUBMITS into the
 * already-resumed conversation — re-running (or, if that persisted text was a slash command like
 * `/clear`, WIPING) the restored history. Mirrors the planner's `startupPromptFreshOnly`
 * (`plannerLaunch`).
 */
export function resolveStartupPromptFreshOnly(s: AppStore, paneId: string, isClaudeProvider: boolean): boolean {
  // NOT gated on the harness. This rule is about RESUMING, and `bsc-agent` resumes too — it takes
  // `--continue`/`-c` deliberately mirroring claude's, and `resolveInitCmd` now emits it. Gating on
  // `isClaudeProvider` made every protection here Claude-only: a local pane never suppressed its
  // kickoff, so it was re-instructed on EVERY launch, and it never took the `Init` arm that carries
  // `--continue` — so `plan_launch` could only ever resume it via `continue_session`, and a local
  // session could not resume at all. `isClaudeProvider` is kept in the signature because callers
  // pass it and a future harness may genuinely differ; it is simply not this rule's business.
  void isClaudeProvider;
  if (isManualPaneId(paneId)) return false;
  // EVERY app-owned studio session (the DEBUG session #3326, and the designer/librarian/architect since
  // #3357) resumes with `claude --continue` across app restarts, so its baked charter/persona kickoff must
  // be fresh-only — delivered on the first launch (no history) but suppressed when it resumes an existing
  // conversation, so returning isn't re-greeted (or, worse, re-instructed). The backend's
  // `fresh_only && has_history` guard makes this exact: a genuinely fresh launch still fires. Reproduces
  // the old `useScreenSession` launches' hardcoded `startupPromptFreshOnly: true`.
  // NOT `isFullCapabilitySession` (the `debug-studio:` PREFIX). It looks like the right predicate and is
  // the bug: it also covers the per-REQUEST debug sessions, and for them fresh-only is exactly wrong.
  //
  // Fresh-only protects a conversation being RESUMED — do not re-greet, do not re-instruct. A
  // per-request session resumes nothing: it launches `claude` fresh with `paneContinue: false` (#3497,
  // one request one session, never inherit another conversation), and its charter is the only thing
  // telling it which request it exists for. Suppressing that leaves it at an empty prompt forever.
  //
  // What made it fire EVERY time is the cwd. `has_history` asks whether claude has run in this
  // DIRECTORY before, and every debug session runs in the base-studio-code repo — where every developer
  // session, worker and other debug session already has. So `fresh_only && has_history` was permanently
  // true and no debug session has ever received its charter. The symptom was "they start but sit idle".
  //
  // The standing `debug-studio:debugger` keeps fresh-only: it is named in the studio pane registry and does
  // genuinely resume (`claude --continue || claude`). That list is the whole of what the prefix was
  // adding beyond it, and the per-request half is the half that was wrong.
  return !!s.restoreRequested[paneId] || isStudioSessionPaneId(paneId);
}
